from decimal import Decimal

import pytest

from pricing import Cart, LineItem
from pricing.bulk_discount import (
    BULK_DISCOUNT_PERCENT,
    BULK_QUANTITY_THRESHOLD,
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)


class TestBulkDiscountThreshold:
    """Tests for Req 1.1, 1.2, 1.3: quantity threshold behavior."""

    @pytest.mark.l4("C-8764baca")
    def test_quantity_exactly_10_qualifies_for_bulk_discount(self):
        """WHEN a line item has a quantity of exactly 10 THEN it qualifies."""
        item = LineItem("widget", Decimal("1.00"), 10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_greater_than_10_qualifies_for_bulk_discount(self):
        """WHEN a line item has a quantity greater than 10 THEN it qualifies."""
        item = LineItem("widget", Decimal("1.00"), 11)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-4284227d")
    def test_quantity_9_does_not_qualify_for_bulk_discount(self):
        """WHEN a line item has a quantity of 9 or fewer THEN it does not qualify."""
        item = LineItem("widget", Decimal("1.00"), 9)
        assert qualifies_for_bulk_discount(item) is False

    @pytest.mark.l4("C-4284227d")
    def test_quantity_1_does_not_qualify_for_bulk_discount(self):
        """WHEN a line item has a quantity of 1 THEN it does not qualify."""
        item = LineItem("widget", Decimal("1.00"), 1)
        assert qualifies_for_bulk_discount(item) is False


class TestBulkDiscountCalculation:
    """Tests for Req 1.4: discount calculation and rounding."""

    @pytest.mark.l4("C-8764baca")
    def test_discount_for_quantity_10_is_5_percent(self):
        """WHEN quantity is exactly 10 THEN discount is 5% of line total."""
        item = LineItem("widget", Decimal("1.00"), 10)
        discount = calculate_bulk_discount(item)
        # 10 items at $1.00 each = $10.00 total, 5% = $0.50
        assert discount == Decimal("0.50")

    @pytest.mark.l4("C-e4015f6b")
    def test_discount_for_quantity_11_is_5_percent(self):
        """WHEN quantity is greater than 10 THEN discount is 5% of line total."""
        item = LineItem("widget", Decimal("1.00"), 11)
        discount = calculate_bulk_discount(item)
        # 11 items at $1.00 each = $11.00 total, 5% = $0.55
        assert discount == Decimal("0.55")

    @pytest.mark.l4("C-4284227d")
    def test_discount_for_quantity_9_is_zero(self):
        """WHEN quantity is 9 THEN discount is zero."""
        item = LineItem("widget", Decimal("1.00"), 9)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_rounds_half_up_to_cents(self):
        """WHEN discount requires rounding THEN it rounds half-up to 0.01."""
        # Create a case where 5% results in 0.125, which should round to 0.13
        # $2.50 total * 5% = $0.125 -> should round to $0.13
        item = LineItem("widget", Decimal("0.25"), 10)  # total = $2.50
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.13")

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_rounds_down_when_appropriate(self):
        """WHEN discount rounds down THEN it rounds to 0.01 correctly."""
        # $2.40 total * 5% = $0.12
        item = LineItem("widget", Decimal("0.24"), 10)  # total = $2.40
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.12")


class TestBulkSavings:
    """Tests for Req 2: Cart.bulk_savings() method."""

    @pytest.mark.l4("C-cc0190d6")
    def test_bulk_savings_sums_qualifying_items(self):
        """WHEN cart has qualifying items THEN bulk_savings sums their discounts."""
        cart = Cart([
            LineItem("widget", Decimal("1.00"), 10),  # $10.00 total, 5% = $0.50
            LineItem("gadget", Decimal("2.00"), 10),  # $20.00 total, 5% = $1.00
        ])
        savings = cart.bulk_savings()
        assert savings == Decimal("1.50")

    @pytest.mark.l4("C-efd8f9b2")
    def test_bulk_savings_with_no_qualifying_items(self):
        """WHEN cart has no qualifying items THEN bulk_savings returns 0.00."""
        cart = Cart([
            LineItem("widget", Decimal("1.00"), 5),
            LineItem("gadget", Decimal("2.00"), 3),
        ])
        savings = cart.bulk_savings()
        assert savings == Decimal("0.00")

