    def test_bulk_savings_empty_cart(self):
        """WHEN cart is empty THEN bulk_savings returns 0.00."""
        cart = Cart()
        savings = cart.bulk_savings()
        assert savings == Decimal("0.00")

    @pytest.mark.l4("C-cc0190d6")
    def test_bulk_savings_with_mixed_qualifying_items(self):
        """WHEN cart has mixed qualifying and non-qualifying items THEN only qualifying count."""
        cart = Cart([
            LineItem("widget", Decimal("1.00"), 10),   # qualifies: $0.50
            LineItem("gadget", Decimal("2.00"), 5),    # does not qualify
            LineItem("thingy", Decimal("1.00"), 11),   # qualifies: $0.55
        ])
        savings = cart.bulk_savings()
        assert savings == Decimal("1.05")

    @pytest.mark.l4("C-ab74596f")
    def test_bulk_savings_rounds_half_up(self):
        """WHEN total bulk savings requires rounding THEN it rounds half-up to 0.01."""
        # Each item: $2.50 total, 5% = $0.125 -> rounds to $0.13
        # Two items = $0.26
        cart = Cart([
            LineItem("widget", Decimal("0.25"), 10),
            LineItem("gadget", Decimal("0.25"), 10),
        ])
        savings = cart.bulk_savings()
        assert savings == Decimal("0.26")


class TestBulkDiscountConstants:
    """Tests for bulk discount constants."""

    @pytest.mark.l4("C-8764baca", "C-e4015f6b", "C-4284227d")
    def test_bulk_quantity_threshold_is_10(self):
